def run_checks(py):
    """Runs every claim under the interpreter py; returns (number of claims run, list of failures)."""
    import json, subprocess
    def sub(args, code=None):
        r = subprocess.run([py] + args, capture_output=True, text=True, timeout=30, input=code); return r
    ver = tuple(int(x) for x in subprocess.run([py, "-c", "import sys;print('%d.%d' % sys.version_info[:2])"], capture_output=True, text=True).stdout.strip().split("."))
    bad = []; n = 0
    exprs = [c for c in CHECKS if len(c) == 2]
    code = ("import json, contextlib, io\nout = []\nfor e, x in %r:\n    with contextlib.redirect_stdout(io.StringIO()):\n        got = repr(eval(e))\n    out.append(got == x or got)\nprint(json.dumps(out))" % (exprs,))
    got = json.loads(sub(["-c", code]).stdout)
    for (e, x), g in zip(exprs, got):
        n += 1
        if g is not True: bad.append((e, x, g))
    for c in CHECKS:
        if len(c) != 3: continue
        n += 1; src, exp, kind = c
        r = sub(["-c", src])
        if kind == "program":
            if r.returncode != 0 or r.stdout != exp: bad.append((src, exp, r.stdout + r.stderr[-200:]))
        elif kind == "traceback":
            lines = r.stderr.strip().splitlines()
            if not (lines and lines[0] == "Traceback (most recent call last):" and lines[-1] == exp): bad.append((src, exp, r.stderr[-300:]))
        elif kind == "stderr":
            if not (r.returncode == 1 and r.stderr.strip() == exp and r.stdout == ""): bad.append((src, exp, (r.returncode, r.stderr, r.stdout)))
    for rz in RAISES:
        code, typ, msg = rz[:3]; lo = rz[3] if len(rz) > 3 else None; hi = rz[4] if len(rz) > 4 else None
        if (lo and ver < lo) or (hi and ver > hi): continue
        n += 1
        probe = ("import sys\nsrc = %r\ntry:\n    exec(compile(src, '<claim>', 'exec'))\nexcept BaseException as e:\n    m = e.msg if isinstance(e, SyntaxError) else str(e)\n    print(type(e).__name__ + '|' + m)\nelse:\n    print('no error')" % code)
        got = sub(["-c", probe]).stdout.strip()
        if got != typ + "|" + msg: bad.append((code, typ + "|" + msg, got))
    return n, bad

if __name__ == "__main__":
    import os, subprocess, sys
    pys = sys.argv[1:] or ["/root/.local/bin/python3.14"]
    if "/root/.local/bin/python3.12" not in pys and os.path.exists("/root/.local/bin/python3.12"): pys = pys + ["/root/.local/bin/python3.12"]
    for py in pys:
        n, bad = run_checks(py)
        print(n, "claims executed under", subprocess.run([py, "--version"], capture_output=True, text=True).stdout.strip(), "- failures:", bad)
    ids = [n[0] for n in NODES]; assert len(ids) == len(set(ids))
    byid = {n[0]: n for n in NODES}
    for n in NODES:
        assert n[3] is None or n[3] in byid, n[0]
        assert (n[2] == 3) == (n[4] is not None), n[0]
        if n[3]: assert byid[n[3]][2] == n[2] - 1, n[0]
        assert 3 <= len(n[5]) <= 6 and (n[2] == 3 and 4 <= len(n[5]) or n[2] < 3), (n[0], len(n[5]))
    for leaf, owner in OWNERS: assert leaf in byid and owner in byid
    for leaf, t in ERRORS: assert leaf in byid
    print(len(NODES), "concepts;", sum(len(n[5]) for n in NODES), "paragraphs;", sum(len(t.split()) for n in NODES for f, t in n[5]), "words;", len(CHECKS) + len(RAISES), "checks")
